INSERT INTO feature VALUES('normalization-by-evaluation','conversion','Normalization by evaluation',NULL,'implemented','notable',NULL,'Terms evaluate into a glued semantic domain and read back to compact normal forms, under a fuel budget that declines rather than refutes. A value the domain shares reads back once at each binder depth, so the core term shares its node wherever the domain does (#3603).','core-nbe','crates/core-nbe/src/readback/tests.rs crates/core-nbe/tests/static_normalization.rs crates/surface-dispatcher/tests/differential.rs','crate-tests',NULL);
